import { describe, expect, it } from 'vitest';

import fixture from './__fixtures__/passage_parity_v1.json';
import { runeCount, splitParagraphs } from './passages';

// The fixture is generated by the Go backend (work_chapter_paragraphs): both
// sides must split a text into the same paragraphs and count runes alike.

describe('passage parity fixture v1', () => {
  it('has the expected schema version', () => {
    expect(fixture.version).toBe(1);
  });

  for (const testCase of fixture.cases) {
    it(`splits «${testCase.name}» like the backend`, () => {
      expect(splitParagraphs(testCase.text)).toEqual(testCase.paragraphs);
    });
  }

  for (const quote of fixture.quotes) {
    it(`counts runes of «${quote.name}» like the backend`, () => {
      expect(runeCount(quote.quote)).toBe(quote.runes);
    });
  }
});
